#!/usr/bin/env bash
export PROMPT_DIRTRIM=3
export SSHP_TERM="${SSHP_TERM:-$TERM}"
export PROMPT_COMMAND='__pc_exit_code=$?;alias sudo='\''sudo --preserve-env=PROMPT_COMMAND,PROMPT_DIRTRIM'\'';sshp() { local __sshp_val_flags="BbcDEeFIiJLlmOopQRSWw";local __sshp_opts=() __sshp_dest="" __sshp_cmd=();local __sshp_end_opts=0 __sshp_arg __sshp_rest __sshp_c __sshp_j;while [[ $# -gt 0 ]]; do __sshp_arg=$1;if [[ -z "$__sshp_dest" && $__sshp_end_opts -eq 0 && "$__sshp_arg" == "--" ]]; then __sshp_end_opts=1;shift;continue;fi;if [[ -z "$__sshp_dest" && $__sshp_end_opts -eq 0 && "$__sshp_arg" == -?* ]]; then __sshp_rest=${__sshp_arg:1};while [[ -n "$__sshp_rest" ]]; do __sshp_c=${__sshp_rest:0:1};__sshp_j=${__sshp_rest:1};if [[ "$__sshp_val_flags" == *"$__sshp_c"* ]]; then if [[ -n "$__sshp_j" ]]; then __sshp_opts+=("-$__sshp_c" "$__sshp_j");else shift;[[ $# -eq 0 ]] && { echo "sshp: option -$__sshp_c requires an argument" >&2; return 1; };__sshp_opts+=("-$__sshp_c" "$1");fi;__sshp_rest="";else __sshp_opts+=("-$__sshp_c");__sshp_rest=$__sshp_j;fi;done;shift;continue;fi;if [[ -z "$__sshp_dest" ]]; then __sshp_dest=$__sshp_arg;else __sshp_cmd+=("$__sshp_arg");fi;shift;done;[[ -z "$__sshp_dest" ]] && { echo "usage: sshp [ssh-opts] [--] <dest> [cmd...]" >&2; return 1; };local __sshp_dirtrim __sshp_promptcmd __sshp_term __sshp_sshpterm;printf -v __sshp_dirtrim %q "$PROMPT_DIRTRIM";printf -v __sshp_promptcmd %q "$PROMPT_COMMAND";printf -v __sshp_term %q "${SSHP_TERM:-${TERM:-xterm-256color}}";printf -v __sshp_sshpterm %q "${SSHP_TERM:-${TERM:-xterm-256color}}";local __sshp_termfix="if ! infocmp \$TERM >/dev/null 2>&1; then export TERM=xterm-256color; fi";if [[ ${#__sshp_cmd[@]} -gt 0 ]]; then ssh "${__sshp_opts[@]}" "$__sshp_dest" "export SSHP_TERM=$__sshp_sshpterm; export TERM=$__sshp_term; $__sshp_termfix; export PROMPT_DIRTRIM=$__sshp_dirtrim; export PROMPT_COMMAND=$__sshp_promptcmd; ${__sshp_cmd[*]}";else ssh -t "${__sshp_opts[@]}" "$__sshp_dest" "export SSHP_TERM=$__sshp_sshpterm; export TERM=$__sshp_term; $__sshp_termfix; if command -v bash >/dev/null 2>&1; then exec env SSHP_TERM=\$SSHP_TERM TERM=\$TERM PROMPT_DIRTRIM=$__sshp_dirtrim PROMPT_COMMAND=$__sshp_promptcmd bash -i; else exec \$SHELL -i; fi";fi;};if [[ "$USER" == "melinoe" ]]; then __pc_main="189;147;249";__pc_symbol="\$";elif [[ "$USER" == "root" ]]; then __pc_main="255;85;85";__pc_symbol="#";else __pc_main="241;250;140";__pc_symbol="\$";fi;__pc_exit_seg="";[[ $__pc_exit_code -ne 0 ]] && __pc_exit_seg="\[\e[38;2;255;85;85m\]\[\e[1m\] ${__pc_exit_code}\[\e[0m\]\n";PS1="${__pc_exit_seg}\[\e[38;2;${__pc_main}m\]\[\e[1m\]\u@\h\[\e[0m\]";PS1+="\[\e[38;2;98;114;164m\]\[\e[0m\]";PS1+="\[\e[38;2;139;233;253m\] \w\[\e[0m\]";PS1+="$( __pc_icon=$'"'"'\ue0a0'"'"';__pc_branch=$(git -c safe.directory="*" symbolic-ref --quiet --short HEAD 2>/dev/null) || __pc_branch=$(git -c safe.directory="*" rev-parse --short HEAD 2>/dev/null);[[ -z "$__pc_branch" ]] && exit;if [[ -n "$(git -c safe.directory="*" status --porcelain 2>/dev/null)" ]]; then __pc_color="255;184;108";else __pc_color="139;233;253";fi;__pc_arrows="";__pc_ab=$(git -c safe.directory="*" rev-list --left-right --count "HEAD...@{upstream}" 2>/dev/null);if [[ -n "$__pc_ab" ]]; then __pc_ahead=${__pc_ab%%$'"'"'\t'"'"'*};__pc_behind=${__pc_ab##*$'"'"'\t'"'"'};[[ "$__pc_ahead" -gt 0 ]] && __pc_arrows+=" \[\e[38;2;255;121;198m\]↑${__pc_ahead}";[[ "$__pc_behind" -gt 0 ]] && __pc_arrows+=" \[\e[38;2;255;121;198m\]↓${__pc_behind}";fi;printf "%s" "\[\e[38;2;98;114;164m\] \[\e[38;2;${__pc_color}m\]${__pc_icon} ${__pc_branch}${__pc_arrows}\[\e[0m\]";)";PS1+=" \[\e[38;2;${__pc_main}m\]\[\e[1m\]${__pc_symbol}\[\e[0m\] ";unset __pc_exit_code __pc_main __pc_symbol __pc_exit_seg'
